from __future__ import annotations

import json
import os
from pathlib import Path

from .model import Entry

CURRENT_VERSION = 1


class JsonStateStore:
    """Reads and writes the whole inbox as a single JSON document."""

    def __init__(self, path):
        self.path = Path(path)

    def load(self) -> dict:
        if not self.path.exists():
            return {}
        raw = json.loads(self.path.read_text(encoding="utf-8"))
        entries = raw.get("entries", {})
        return {key: Entry.from_dict(dict(item, key=key))
                for key, item in entries.items()}

    def save(self, entries, next_seq) -> None:
        doc = {"version": CURRENT_VERSION,
               "entries": {key: entry.to_dict()
                           for key, entry in sorted(entries.items())}}
        tmp = self.path.with_name(self.path.name + ".tmp")
        tmp.write_text(json.dumps(doc, sort_keys=True, indent=2), encoding="utf-8")
        os.replace(tmp, self.path)

