from __future__ import annotations

import json
import time

from .errors import LeaseError, UnknownKeyError, ValidationError
from .model import Entry
from .store import JsonStateStore


def _check_text(value, label):
    if not isinstance(value, str):
        raise ValidationError(f"{label} must be a string")
    return value


class Inbox:
    """A durable multi-session request inbox."""

    def __init__(self, path, clock=time.time):
        self._clock = clock
        self._store = JsonStateStore(path)
        self._entries = self._store.load()
        self._next_seq = len(self._entries) + 1

    @property
    def next_seq(self):
        return self._next_seq

    def _now(self):
        return float(self._clock())

    def _flush(self):
        self._store.save(self._entries, self._next_seq)

    def submit(self, key, payload):
        _check_text(key, "key")
        if not isinstance(payload, dict):
            raise ValidationError("payload must be a dict")
        now = self._now()
        entry = self._entries.get(key)
        if entry is None:
            entry = Entry(key=key, seq=self._next_seq, payload=dict(payload),
                          created_at=now, updated_at=now)
            self._entries[key] = entry
            self._next_seq += 1
            self._flush()
            return entry
        if json.dumps(entry.payload) == json.dumps(payload):
            return entry
        entry.payload = dict(payload)
        entry.updated_at = now
        self._flush()
        return entry

    def claim(self, owner, lease_seconds, limit=1):
        _check_text(owner, "owner")
        if lease_seconds <= 0:
            raise ValidationError("lease_seconds must be positive")
        now = self._now()
        claimed = []
        for entry in sorted(self._entries.values(), key=lambda e: e.seq):
            if len(claimed) >= limit:
                break
            if entry.state != "pending":
                continue
            entry.state = "claimed"
            entry.owner = owner
            entry.lease_expires_at = now + lease_seconds
            entry.updated_at = now
            claimed.append(entry)
        if claimed:
            self._flush()
        return claimed

    def ack(self, key, owner, result=None):
        _check_text(key, "key")
        _check_text(owner, "owner")
        entry = self._entries.get(key)
        if entry is None:
            raise UnknownKeyError(f"unknown key: {key!r}")
        if entry.state != "claimed":
            raise LeaseError(f"{key!r} is not claimed")
        entry.state = "done"
        entry.owner = None
        entry.lease_expires_at = None
        entry.updated_at = self._now()
        self._flush()
        return entry

    def sweep(self):
        now = self._now()
        expired = 0
        for entry in self._entries.values():
            if entry.lease_expired(now):
                entry.state = "pending"
                entry.owner = None
                entry.lease_expires_at = None
                entry.updated_at = now
                expired += 1
        if expired:
            self._flush()
        return expired

    def get(self, key):
        return self._entries.get(key)

    def list_entries(self, state=None):
        items = sorted(self._entries.values(), key=lambda e: e.key)
        return [e for e in items if state is None or e.state == state]

