"""Durable JSON state file for the inbox."""

from __future__ import annotations

import json
import os
from pathlib import Path

from .errors import StateFormatError
from .model import Entry

CURRENT_VERSION = 2
SUPPORTED_VERSIONS = (1, 2)


class JsonStateStore:
    """Reads and writes the whole inbox as a single JSON document."""

    def __init__(self, path):
        self.path = Path(path)

    def load(self) -> dict:
        if not self.path.exists():
            return {}
        try:
            raw = json.loads(self.path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            raise StateFormatError(f"unreadable state file: {exc}") from exc
        if not isinstance(raw, dict):
            raise StateFormatError("state file must hold a JSON object")
        version = raw.get("version")
        if isinstance(version, bool) or not isinstance(version, int):
            raise StateFormatError(f"invalid state version: {version!r}")
        if version not in SUPPORTED_VERSIONS:
            raise StateFormatError(f"unsupported state version: {version!r}")
        entries = raw.get("entries")
        if not isinstance(entries, dict):
            raise StateFormatError("state file has no entries object")
        loaded = {}
        for key, item in entries.items():
            if not isinstance(item, dict):
                raise StateFormatError(f"entry {key!r} is not a JSON object")
            loaded[key] = Entry.from_dict(dict(item, key=key))
        return loaded

    def save(self, entries, next_seq) -> None:
        doc = {
            "version": CURRENT_VERSION,
            "next_seq": next_seq,
            "entries": {key: entry.to_dict()
                        for key, entry in sorted(entries.items())},
        }
        self.path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.path.with_name(self.path.name + ".tmp")
        tmp.write_text(json.dumps(doc, sort_keys=True, indent=2), encoding="utf-8")
        os.replace(tmp, self.path)

