"""The inbox service: submissions, leases, acknowledgements and expiry."""

from __future__ import annotations

import copy
import json
import math
import time

from .errors import ConflictError, LeaseError, UnknownKeyError, ValidationError
from .model import STATES, Entry, SubmitResult
from .store import JsonStateStore


def _canonical(payload):
    return json.dumps(payload, sort_keys=True, separators=(",", ":"))


def _check_text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValidationError(f"{label} must be a non-empty string")
    return value


def _check_mapping(value, label):
    if not isinstance(value, dict):
        raise ValidationError(f"{label} must be a dict")
    if any(not isinstance(name, str) for name in value):
        raise ValidationError(f"{label} keys must be strings")
    try:
        _canonical(value)
    except (TypeError, ValueError) as exc:
        raise ValidationError(f"{label} must be JSON serialisable") from exc
    return copy.deepcopy(value)


def _check_seconds(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValidationError(f"{label} must be a number")
    number = float(value)
    if not math.isfinite(number) or number <= 0:
        raise ValidationError(f"{label} must be finite and positive")
    return number


def _check_limit(value):
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise ValidationError("limit must be an int >= 1")
    return value


def _check_revision(value):
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise ValidationError("revision must be an int >= 1")
    return value


class Inbox:
    """A durable multi-session request inbox backed by a JSON state file."""

    def __init__(self, path, clock=time.time):
        if not callable(clock):
            raise ValidationError("clock must be callable")
        self._clock = clock
        self._store = JsonStateStore(path)
        self._entries = self._store.load()
        self._next_seq = max((e.seq for e in self._entries.values()), default=0) + 1

    @property
    def path(self):
        return self._store.path

    @property
    def next_seq(self):
        return self._next_seq

    def _now(self):
        return float(self._clock())

    def _flush(self):
        self._store.save(self._entries, self._next_seq)

    def _expire(self, now):
        expired = 0
        for entry in self._entries.values():
            if entry.lease_expired(now):
                entry.state = "pending"
                entry.owner = None
                entry.lease_expires_at = None
                entry.updated_at = now
                expired += 1
        if expired:
            self._flush()
        return expired

    def _leased(self, key, owner):
        entry = self._entries.get(key)
        if entry is None:
            raise UnknownKeyError(f"unknown key: {key!r}")
        if entry.state != "claimed":
            raise LeaseError(f"{key!r} is not claimed")
        if entry.owner != owner:
            raise LeaseError(f"{key!r} is claimed by {entry.owner!r}")
        return entry

    def submit(self, key, payload):
        _check_text(key, "key")
        fresh = _check_mapping(payload, "payload")
        now = self._now()
        entry = self._entries.get(key)
        if entry is None:
            entry = Entry(key=key, seq=self._next_seq, payload=fresh,
                          state="pending", revision=1, attempts=0,
                          created_at=now, updated_at=now)
            self._entries[key] = entry
            self._next_seq += 1
            self._flush()
            return SubmitResult(entry.copy(), True, False)
        if _canonical(entry.payload) == _canonical(fresh):
            return SubmitResult(entry.copy(), False, False)
        entry.payload = fresh
        entry.revision += 1
        entry.state = "pending"
        entry.owner = None
        entry.lease_expires_at = None
        entry.result = None
        entry.updated_at = now
        self._flush()
        return SubmitResult(entry.copy(), False, True)

    def claim(self, owner, lease_seconds, limit=1):
        _check_text(owner, "owner")
        seconds = _check_seconds(lease_seconds, "lease_seconds")
        _check_limit(limit)
        now = self._now()
        self._expire(now)
        claimed = []
        for entry in sorted(self._entries.values(), key=lambda e: e.seq):
            if len(claimed) >= limit:
                break
            if entry.state != "pending":
                continue
            entry.state = "claimed"
            entry.owner = owner
            entry.lease_expires_at = now + seconds
            entry.attempts += 1
            entry.updated_at = now
            claimed.append(entry.copy())
        if claimed:
            self._flush()
        return claimed

    def ack(self, key, owner, result=None, *, revision=None):
        _check_text(key, "key")
        _check_text(owner, "owner")
        outcome = None if result is None else _check_mapping(result, "result")
        _check_revision(revision)
        now = self._now()
        self._expire(now)
        entry = self._leased(key, owner)
        if revision is not None and revision != entry.revision:
            raise ConflictError(f"{key!r} is at revision {entry.revision}")
        entry.state = "done"
        entry.result = outcome
        entry.acked_revision = entry.revision
        entry.owner = None
        entry.lease_expires_at = None
        entry.updated_at = now
        self._flush()
        return entry.copy()

    def release(self, key, owner):
        _check_text(key, "key")
        _check_text(owner, "owner")
        now = self._now()
        self._expire(now)
        entry = self._leased(key, owner)
        entry.state = "pending"
        entry.owner = None
        entry.lease_expires_at = None
        entry.updated_at = now
        self._flush()
        return entry.copy()

    def sweep(self):
        return self._expire(self._now())

    def get(self, key):
        _check_text(key, "key")
        entry = self._entries.get(key)
        return None if entry is None else entry.copy()

    def list_entries(self, state=None):
        if state is not None and state not in STATES:
            raise ValidationError(f"unknown state: {state!r}")
        items = sorted(self._entries.values(), key=lambda e: e.seq)
        return [e.copy() for e in items if state is None or e.state == state]

    def stats(self):
        counts = {name: 0 for name in STATES}
        for entry in self._entries.values():
            counts[entry.state] += 1
        counts["total"] = len(self._entries)
        return counts
